#include "../Source/NativeRackEngines.h"
#include <cstdio>
#include <cstdlib>
#include <new>
using namespace skl;
static bool callback=false;static size_t allocations=0,deletions=0;
void* operator new(size_t n){if(callback)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void* operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{if(callback&&p)++deletions;std::free(p);}void operator delete[](void*p)noexcept{::operator delete(p);}void operator delete(void*p,size_t)noexcept{::operator delete(p);}void operator delete[](void*p,size_t)noexcept{::operator delete(p);}
static void check(bool b,const char* msg){if(!b){std::fprintf(stderr,"FAIL %s\n",msg);std::exit(1);}}
static float render(ModuleBase& a,ModuleBase& b,const float* k,int sr,int seconds){float maxError=0;std::array<float,257> al{},ar{},bl{},br{};float* ap[]={al.data(),ar.data()},*bp[]={bl.data(),br.data()};a.setTempo(30);b.setTempo(30);for(int i=0;i<sr*seconds;i+=257){const int n=std::min(257,sr*seconds-i);for(int j=0;j<n;++j){al[j]=bl[j]=.24f*std::sin(2*kPi*317*(i+j)/sr)+((i+j)%991==0?.1f:0.f);ar[j]=br[j]=.18f*std::cos(2*kPi*707*(i+j)/sr);}juce::AudioBuffer<float>x(ap,2,0,n),y(bp,2,0,n);callback=true;a.process(x,k,true);b.process(y,k,true);callback=false;for(int j=0;j<n;++j){check(std::isfinite(al[j])&&std::isfinite(ar[j]),"finite");maxError=std::max({maxError,std::abs(al[j]-bl[j]),std::abs(ar[j]-br[j])});}}return maxError;}
int main(){for(int sr:{44100,48000,96000,192000}){SlotDelayArena arena;NativeDelayRack delay,delayRef;NativeGlitchRack glitch,glitchRef;{SlotDelayPreparation scope(arena);delay.prepare(sr,257,2);}{SlotDelayPreparation scope(arena);glitch.prepare(sr,257,2);}delayRef.prepare(sr,257,2);glitchRef.prepare(sr,257,2);float d[6],g[6];for(int i=0;i<6;++i){d[i]=defaultNorm(DelayNative,i);g[i]=defaultNorm(GlitchNative,i);}d[0]=.1f;d[5]=1;g[0]=0;g[1]=1;g[4]=.5f;g[5]=1;float err=0;for(int cycle=0;cycle<2;++cycle){callback=true;delay.reset();delayRef.reset();callback=false;err=std::max(err,render(delay,delayRef,d,sr,2));callback=true;glitch.reset();glitchRef.reset();callback=false;err=std::max(err,render(glitch,glitchRef,g,sr,17));}check(err<2e-6f,"shared slot parity after cross-effect overwrite");std::printf("%d Hz: shared delay/glitch 8s reverse capture & repeated switch error %.9g, arena %.2f MiB\n",sr,err,arena.storage->size()*4./1048576.);}
// High-rate admission of eight taps (persistent limit, temporary peak reserve).
{NativeDelayRack d;auto budget=std::make_shared<native_delay::RackBudget>();d.setBudget(budget);d.prepare(192000,257,2);auto ext=nativeDefaults();ext[nDelayModel]=1;ext[nDelayBanks]=1;float k[6];for(int j=0;j<6;++j)k[j]=defaultNorm(DelayNative,j);d.setExtended(ext);check(d.service(ext,k,true),"192k eight-bank prepare");check(budget->used()<=128u*native_delay::MiB,"persistent cap");std::printf("192k 8 taps persistent reservation %.2f MiB\n",budget->used()/1048576.);}
check(allocations==0&&deletions==0,"callback allocation/deletion");std::puts("Shared native storage and high-rate budget passed");}
